/**
 * Der Lernplan des Bereichs „Lernen“ (Fachblatt docs/fachblaetter/LERNPLAN.md): kleine Einheiten und Lernpfade. Reine Daten; alles bleibt frei anklickbar.
 * Jede Einheit verbindet, was es schon gibt: Hilfe-Artikel und Begriffe (`hilfe`, der erste ist die Erklärung), Schritte aus den Beispielen (`beispiele`),
 * Regler unter „Verstehen“ (`probieren`, Teil der Adresse nach `#verstehen/`) und Übungsfragen (`fragen`, Kennungen aus `fragen-*.ts`).
 * Fragen werden nur hier einer Einheit zugeordnet; der Wächter `lernplan.test.ts` hält die Zuordnung vollständig. Fehlen einer Einheit noch Teile, steht es in `fehlt`.
 */
import { P, type Paar } from '../i18n/laufzeit';
import { EINHEITEN_VV, PFAD_VV } from './lernplan-vv';
import { EINHEITEN_SF, PFAD_SF } from './lernplan-sf';
