import { EINHEITEN_NETZWERK } from './lernplan-netzwerk';
import { EINHEITEN_PROFILE } from './lernplan-profile';
import { EINHEITEN_KLASSEN } from './lernplan-klassen';
import { EINHEITEN_PLANUNG } from './lernplan-planung';
import { EINHEITEN_TEXTANALYSE } from './lernplan-textanalyse';
import { EINHEITEN_DELPHI } from './lernplan-delphi';
import { EINHEITEN_QMETHODE } from './lernplan-qmethode';
import { EINHEITEN_CONCEPTMAP } from './lernplan-conceptmap';
import { EINHEITEN_PAPIERBOGEN } from './lernplan-papierbogen';
import { EINHEITEN_ERHEBEN, PFAD_ERHEBEN, PFAD_INTERVIEWS, PFAD_MIXED, PFAD_FEINSTRUKTUR } from './lernplan-erheben';
import { EINHEITEN_NUTZEN } from './lernplan-nutzen';
import { EINHEITEN_NB } from './lernplan-nutzen-b';
import { EINHEITEN_PM } from './lernplan-pruefschritte';

export type BereichId = 'daten' | 'beschreiben' | 'verteilung' | 'wahrscheinlichkeit' | 'schliessen' | 'planen' | 'vergleichen' | 'zusammenhang' | 'vorhersage' | 'kategorien' | 'messen' | 'technik' | 'fach' | 'abschluss';

export interface Einheit {
  id: string;
  /** Die Alltagsfrage; der Fachbegriff (`fach`) steht in der Überschrift immer dabei. */
  alltag: Paar; fach: Paar;
  bereich: BereichId;
  /** Hilfe-Artikel oder Begriffe; der erste ist die Erklärung, die übrigen sind aufklappbar. */
  hilfe: string[];
  /** Rechenaufgaben zum Selbst-Rechnen (Kennungen aus `rechenaufgaben.ts`); der Abschnitt folgt direkt auf die Erklärung, vor Beispiel und Regler. */
  rechnen?: string[];
  /** Schritte aus `lib/beispiele.ts` (Beispiel-Id und Nummer des Schritts ab 0). */
  beispiele: { id: string; schritt: number }[];
  /** Regler: Teil der Adresse nach `#verstehen/` (zum Beispiel `effekt` oder `lernlabor/baum`). */
  probieren: string[];
  /** Rechenkarte in Statable (Id aus `lib/verfahren.ts`). */
  karte?: string;
  /** Ausprobieren auf einer Seite von Statable (Erheben, Paket 2H): Adresse mit `#` und Name des Ziels; erscheint als Link unter der Erklärung. */
  ausprobieren?: { adresse: string; titel: Paar }[];
  /** Kennungen der Übungsfragen, in der Reihenfolge der Fragedateien; die Fragen einer Fallreihe stehen beieinander. */
  fragen: string[];
  /** Nur Abschluss-Einheiten: der Pfad, dessen Abschlusstest die Einheit ist (Seite `PfadAbschluss`, kein eigener Inhalt). */
  abschlussVon?: string;
  /** Was für die Zielzahl noch fehlt (Lückenliste im Fachblatt); die Oberfläche zeigt es nicht. */
  fehlt?: { fragen: number; beispiel: boolean; artikel: boolean };
}
/** `abschluss`: Kennungen der Fragen des Abschlusstests (`#lernen/pruefung/<pfad>`); sie stehen in keiner Einheit, jede führt über `zurueck` zu einer. Ohne Eintrag wird der Test aus den Einheitsfragen zusammengestellt. */
export interface Pfad { id: string; name: Paar; einheiten: string[]; abschluss?: string[]; /** Kennung des nächsten Teils: dorthin führt ein „Weiter mit …“-Link am Ende. */ weiter?: string;
  /** Nur eigene Pfade mit Übungsblatt (V3): `abschluss` sind die gewählten Fragen; gemischt und vorgesehene Zeit als Hinweis. */ uebung?: { mischen: boolean; minuten?: number } }

