/** Abschlusstests mit eigenen Fragen (Tabellen zum Deuten); jede Frage führt über `zurueck` zur Einheit zum Üben. */
const ABSCHLUSS: Record<string, string[]> = {
  'regression-lesen': ['ab-rg-le-variablen', 'ab-rg-le-b', 'ab-rg-le-se', 'ab-rg-le-r2', 'ab-rg-le-murder', 'ab-rg-le-illit', 'ab-rg-pe-konstante', 'ab-rg-pe-beta', 'ab-rg-pe-groesse', 'ab-rg-pe-modelle',
    'ab-rg-hs-vis', 'ab-rg-hs-wert', 'ab-rg-hs-schluss', 'ab-rg-hs-skala',
    'ab-rg-sa-b', 'ab-rg-sa-se', 'ab-rg-sa-beta', 'ab-rg-sa-mittel', 'ab-rg-sa-aenderung'],
  fragebogen: ['ab-fb-inhalt', 'ab-fb-zuordnung', 'ab-fb-leer', 'ab-fb-negativ', 'ab-fb-erkennen', 'ab-fb-alpha', 'ab-fb-loeschen', 'ab-fb-gesamt',
    'ab-fc-inhalt', 'ab-fc-zuordnung', 'ab-fc-doppel', 'ab-fc-erkennen', 'ab-fc-wichtig', 'ab-fc-gesamt']
};
for (const p of PFADE) { const a = ABSCHLUSS[p.id]; if (a) p.abschluss = a; }

/**
 * Zu jedem Lernpfad gehört als letzte Einheit sein Abschlusstest (`abschluss-<pfad>`, Name „Abschlusstest: <Pfadname>“). Er ist eine Einheit wie jede andere:
 * man findet sie unter „Abschlusstests“ und kann sie in eigene Pfade übernehmen. Inhalt und Zusammenstellung: `bausteine/PfadAbschluss.svelte`.
 */
for (const p of PFADE) {
  const id = `abschluss-${p.id}`;
  EINHEITEN.push({
    id, bereich: 'abschluss', abschlussVon: p.id,
    alltag: { de: `Habe ich „${p.name.de}“ verstanden?`, en: `Have I understood "${p.name.en}"?` },
    fach: { de: `Abschlusstest: ${p.name.de}`, en: `Final test: ${p.name.en}` },
    hilfe: [], beispiele: [], probieren: [], fragen: []
  });
  p.einheiten.push(id);
}

/** Das Themenmodul (`fragen-<thema>.ts`) einer Frage, erkannt am Anfang ihrer Kennung; der Wächter prüft es gegen das Feld `thema` jeder Frage. */
const THEMA_NACH_ANFANG: Record<string, string> = {
  faktor: 'faktor', skala: 'skala', reg: 'regression', inf: 'inferenz', gr: 'gruppen', kor: 'korrelation', kr: 'kreuz', wa: 'wahrscheinlichkeit',
  med: 'medizin', tech: 'technik', bio: 'biologie', psy: 'psychologie', wi: 'wirtschaft',
  sk: 'beschreiben', lm: 'beschreiben', vd: 'beschreiben', zw: 'beschreiben', nv: 'verteilung', wv: 'verteilung', sv: 'verteilung', bt: 'verteilung',
  log: 'logistisch', gu: 'logistisch', wk: 'logistisch', lgm: 'wachstum', nw: 'netzwerk', lpr: 'profile', lkl: 'klassen', pan: 'panel', iv: 'iv', did: 'did', rd: 'rd',
  um: 'daten', fw: 'daten', ar: 'daten',
  vw: 'planen', fz: 'planen', sz: 'planen', sd: 'planen',
  mw: 'vergleich', mn: 'vergleich', vg: 'vergleich', ef: 'vergleich', tt: 'vergleich', rt: 'vergleich',
  kp: 'messen', is: 'messen', fb: 'fragebogenbau', ab: 'abschluss',
  lmo: 'linmodell', rp: 'regpruefen', vv: 'vavertiefen', sf: 'sauberforschen', ve: 'verfahren', mo: 'modelle', ka: 'karten', zr: 'zeit', da: 'datenwerkzeuge', rc: 'rechner', eh: 'erheben', bx: 'beispiele',
  np: 'nutzenpsy', nb: 'nutzenb', psy2: 'psychologie2', pm: 'pruefschritte', ml: 'ml'
};
export const themaDerFrage = (id: string): string | undefined => THEMA_NACH_ANFANG[id.split('-')[0]!];
/** Die Themenmodule, aus denen die Fragen einer Einheit kommen. */
export const fragenThemen = (e: Einheit): string[] => [...new Set(e.fragen.map(themaDerFrage).filter((t): t is string => !!t))];

/** Einheiten, die es nur zur Laufzeit gibt: die Abschlussprüfungen eigener Pfade (`lib/eigenepfade.svelte.ts` trägt sie ein). */
export const DYNAMISCH = new Map<string, Einheit>();
export const einheitNach = (id: string): Einheit | undefined => EINHEITEN.find(e => e.id === id) ?? DYNAMISCH.get(id);
export const pfadNach = (id: string): Pfad | undefined => PFADE.find(p => p.id === id);
